    vector<ll> v(n);
    for (int i = 0; i < n; ++i) {
        cin >> v[i];
    }
    string t;
    cin >> t;

    // 极性系数
    vector<int> p(n);
    for (int i = 0; i < n; ++i) {
        p[i] = (t[i] == '1') ? 1 : -1;
    }

    // 基础效用 base = sum(p_i * (v_i + 1))
    ll base = 0;
    for (int i = 0; i < n; ++i) {
        base += (ll)p[i] * (v[i] + 1);
    }

    // 后缀和
    vector<ll> suf(n);
    suf[n - 1] = p[n - 1];
    for (int i = n - 2; i >= 0; --i) {
        suf[i] = suf[i + 1] + p[i];
    }

    // 收集正贡献切割点
    vector<ll> contribs;
    for (int i = 0; i < n - 1; ++i) {
        if (suf[i + 1] > 0) {
            contribs.push_back(suf[i + 1]);
